import{z as B,x as A,o as n,c as d,q as i,j as s,D as r,d as e,s as l,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SIMD 与向量化","description":"","frontmatter":{"title":"SIMD 与向量化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-simd-vectorization.md","filePath":"cs/par-simd-vectorization.md","lastUpdated":1791063341000}'),p={name:"cs/par-simd-vectorization.md"};function m(c,a,D,f,C,h){const t=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=i('<h1 id="simd-与向量化" tabindex="-1">SIMD 与向量化 <a class="header-anchor" href="#simd-与向量化" aria-label="Permalink to &quot;SIMD 与向量化&quot;">​</a></h1><div class="epigraph"><p>同一条指令驱动十六条 lane：没有锁，没有调度，没有一致性流量——向量是并行里最便宜的那一档。</p><footer>—— 据 Backus, Can Programming Be Liberated from the von Neumann Style?, CACM 1979；Flynn 分类整理</footer></div><p><a href="/cs/par-lockfree">上一课</a>处理的都是多核之间的协调；本课转向单核内部最便宜的并行。硬件侧已有课垫底：<a href="/cs/simd-vector">SIMD 与向量</a>给了数据级并行的位置，<a href="/cs/simd-extensions">SIMD 扩展：SSE / AVX / NEON</a>与 <a href="/cs/rvv-vector">RISC-V 向量扩展 RVV</a>给了指令集对照，<a href="/cs/vector-lanes">向量处理器与 lane</a>给了 lane 流水，<a href="/cs/flynn-taxonomy">Flynn 分类</a>把格子画好。缺口在软件侧：什么样的循环能被打进向量寄存器、编译器替你做到哪一步、什么时候必须亲手写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>向量化的中心问题是规律性：迭代之间没有依赖（或只有允许改变次序的归约依赖）、访问连续、地址对齐、分支能用掩码表达。任何一条破掉，代码就在那一点退回标量。错法一：以为加一条 pragma 就快若干倍——别名未声明、<code>if</code> 密集、内层循环太短，任何一处都让编译器放弃，或生成一条掩码慢径与快径并存的版本化代码。错法二：在带宽墙下的内核上追峰值算力——<a href="/cs/roofline-model">Roofline 模型</a>先画好了图：强度上不去，向量宽度翻倍也白翻；这正是本课程最后收束的伏笔。</p><p><span class="marginnote">数字实例：256 位 AVX2 寄存器一次装 8 个 32 位浮点——1000 个元素的循环，主循环只要跑 \\(1000/8=125\\) 轮。理论加速上限就是这条「宽度比」；但若每次迭代还要从 DRAM 现搬数据，带宽跟不上，8 倍宽度也只换来 8 分之一轮的空转。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先让编译器做。<a href="/cs/auto-vectorization">自动向量化</a>的依赖分析认得「迭代独立」与「归约」两类可打的模式；别名用 <code>restrict</code> 声明消除，或生成运行时检查的版本化代码——入口判断一次，循环体里各自向量化；循环组织成 peel/main/remainder 三段，对齐的主循环用宽寄存器，余数用短向量或掩码收尾。编译器放弃时才手写 intrinsics 或调库（BLAS 一类），并把分支改写成掩码、把 gather 改回规整访问。验收只认端到端时间与计数器，不认「汇编看上去向量了」。</p><p><span class="marginnote">peel/main/remainder 可以翻译成「零头—正餐—尾巴」：数组起始地址未必对齐到 32 字节，先把开头几个「零头」用标量或短向量磨掉（peel），中间对齐的「正餐」用满宽寄存器跑（main），结尾不足 8 个的「尾巴」用掩码或短向量收掉（remainder）。三段拼起来，才是向量化的完整循环。</span></p>',9)),(n(),s(o,null,{default:r(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%A0%87%E9%87%8F%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20D%7B%22%E8%BF%AD%E4%BB%A3%E9%97%B4%E4%BE%9D%E8%B5%96%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%9C%89%E4%B8%94%E9%9D%9E%E5%BD%92%E7%BA%A6%22%7C%20SC%5B%22%E4%BF%9D%E6%8C%81%E6%A0%87%E9%87%8F%EF%BC%8C%E6%88%96%E6%94%B9%E5%86%99%E7%AE%97%E6%B3%95%22%5D%0A%20%20D%20--%3E%7C%22%E6%97%A0%EF%BC%8C%E6%88%96%E5%BD%92%E7%BA%A6%E5%8F%AF%E9%87%8D%E6%8E%92%22%7C%20AL%7B%22%E5%88%AB%E5%90%8D%E4%B8%8E%E5%AF%B9%E9%BD%90%E6%98%8E%E7%A1%AE%3F%22%7D%0A%20%20AL%20--%3E%7C%22%E4%B8%8D%E6%98%8E%E7%A1%AE%22%7C%20VER%5B%22restrict%20%E5%A3%B0%E6%98%8E%E6%88%96%E7%89%88%E6%9C%AC%E5%8C%96%22%5D%0A%20%20AL%20--%3E%7C%22%E6%98%8E%E7%A1%AE%22%7C%20VEC%5B%22%E5%90%91%E9%87%8F%E4%B8%BB%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20VEC%20--%3E%20REM%5B%22%E4%BD%99%E6%95%B0%EF%BC%9A%E6%8E%A9%E7%A0%81%E6%88%96%E7%9F%AD%E5%90%91%E9%87%8F%E6%94%B6%E5%B0%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("向量为什么便宜：一条取指译码驱动 \\(k\\) 条 lane，控制开销按 \\(k\\) 摊薄，每运算能耗比加核低得多——GPU 用 "),E("a",{href:"/cs/gpu-simt"},"SIMT"),e(" 把同一思想放大成上千 lane，控制包装不同，内核相同。掩码执行的机制是「两条路径都算、按掩码合并」：分支密集时你在给不走的路径付费——SIMT 的发散是同一机制的线程版。gather/scatter 的机制短板：不规则下标让每条 lane 各自访存，规律性红利消失——上一课数据并行的「形状规则」在这里兑现成速度差。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},[e("常见误区：初学者以为向量代码里的 "),E("code",null,"if"),e(" 像 CPU 分支一样「跳过不执行」。实际掩码执行是真、假两条路径都算一遍，再逐 lane 挑选结果——分支越密，白算的越多。这也是「分支密集循环难向量化」的机制根源，GPU warp 发散只是它的线程版。")])],-1)),a[6]||(a[6]=E("p",null,"方法一节画的是「能不能向量化」的判断流；一个带分支的循环被掩码机制消化时钱花在哪，是另一个问题。",-1)),(n(),s(o,null,{default:r(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%A0%87%E9%87%8F%3A%20if%20%E8%B5%B0%E7%9C%9F%E8%B7%AF%20else%20%E8%B5%B0%E5%81%87%E8%B7%AF%22%5D%20--%3E%20V%5B%22%E5%90%91%E9%87%8F%3A%20%E4%B8%A4%E8%B7%AF%E9%83%BD%E7%AE%97%22%5D%0A%20%20V%20--%3E%20T%5B%22%E7%9C%9F%E8%B7%AF%E5%BE%84%E6%95%B4%E6%89%B9%E7%AE%97%E4%B8%80%E4%BB%BD%22%5D%0A%20%20V%20--%3E%20F%5B%22%E5%81%87%E8%B7%AF%E5%BE%84%E4%B9%9F%E6%95%B4%E6%89%B9%E7%AE%97%E4%B8%80%E4%BB%BD%22%5D%0A%20%20T%20--%3E%20M%5B%22%E6%8C%89%E6%8E%A9%E7%A0%81%E9%80%90%20lane%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20F%20--%3E%20M%0A%20%20M%20--%3E%20C%5B%22%E4%B8%8D%E8%B5%B0%E7%9A%84%20lane%20%E7%99%BD%E4%BB%98%E8%B4%B9%3A%20%E5%88%86%E6%94%AF%E8%B6%8A%E5%AF%86%E4%BB%A3%E4%BB%B7%E8%B6%8A%E5%A4%A7%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">部分 CPU 对重负载 AVX-512 分档降频：宽寄存器在频率墙上打折。「512 位一定更快」要用端到端时间验证，不能数指令条数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指令集编码差异——定宽寄存器与变长 VL——已在 simd-extensions 与 RVV 两课给过，不重复；SMT 是同一核上另一维并行，与向量共享端口，混用时互相抢资源，点到为止；GPU warp 的编程侧归专门的 GPU 编程课。本课也不立「向量比例」当指标：向量化是手段，墙位与端到端时间才是账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>向量化是单核内最便宜的并行；前提是规律性：无依赖、连续、对齐、可掩码。</li><li>先自动后手写；编译器放弃的点通常是别名、分支与余数。</li><li>掩码执行给不走的路径付费；gather 丢掉规律性红利。</li><li>强度上不去，向量宽度翻倍也白翻——roofline 收束的伏笔。</li><li>出处：Backus, CACM 1979；Flynn, 1966；Hennessy and Patterson, CA:AQA 数据级并行。</li></ul>',5))])}const S=B(p,[["render",m]]);export{u as __pageData,S as default};
